export default function f({ body }) {
  if (!body?.meetingId) throw Error("Missing meetingId");
  return {
    meetingId: body.meetingId,
    query: {
      query:
        "query Transcript($transcriptId: String!) { transcript(id: $transcriptId) { title participants sentences { speaker_name text } summary { bullet_gist } } }",
      variables: { transcriptId: body.meetingId },
    },
  };
}

