export default function transcript({ body, meetingId }) {
  if (body?.errors?.length || !body?.data?.transcript)
    throw Error("Fireflies transcript unavailable");
  const t = body.data.transcript;
  if (!t.title || !Array.isArray(t.participants) || !Array.isArray(t.sentences))
    throw Error("Invalid Fireflies transcript");
  return {
    project: /project/i.test(t.title),
    transcript: JSON.stringify(t),
    participants: t.participants,
    summary: t.summary?.bullet_gist ?? "",
    meetingId,
  };
}

