export default async function next(
  {
    meetingId,
    plan,
    participants,
    summary,
    baseId,
    table,
    calendarId,
    ownerEmail,
    acknowledge,
    resolution,
  },
  ctx,
) {
  if (
    !meetingId ||
    !baseId ||
    baseId.includes("YOUR_") ||
    !table ||
    !calendarId ||
    calendarId.includes("YOUR_") ||
    !ownerEmail ||
    ownerEmail.includes("YOUR_")
  )
    throw Error("Configure meeting and destinations");
  const key = "fireflies:" + meetingId;
  let s = await ctx.state.get(key);
  if (!s) {
    if (
      !Array.isArray(plan.tasks) ||
      !Array.isArray(plan.notifications) ||
      !Array.isArray(plan.events)
    )
      throw Error("Invalid analysis");
    const allowed = new Set(participants.map((x) => String(x).toLowerCase()));
    for (const n of plan.notifications)
      if (
        !allowed.has(n.email?.toLowerCase()) ||
        n.email.toLowerCase() === ownerEmail.toLowerCase()
      )
        throw Error("Notification recipient not a participant");
    for (const e of plan.events)
      if (
        !e.start ||
        !e.end ||
        !e.attendee ||
        !allowed.has(e.attendee.toLowerCase()) ||
        !Number.isFinite(Date.parse(e.start)) ||
        !Number.isFinite(Date.parse(e.end)) ||
        Date.parse(e.end) <= Date.parse(e.start)
      )
        throw Error("Event lacks explicit valid time or participant");
    s = { plan, summary, phase: "tasks", index: 0, pending: null };
    await ctx.state.set(key, s);
  }
  if (s.pending) {
    if (acknowledge !== s.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending " + s.pending);
    if (resolution === "confirmed") s.index++;
    s.pending = null;
    await ctx.state.set(key, s);
  }
  while (s.phase !== "done" && s.index >= s.plan[s.phase].length) {
    s.phase = { tasks: "notifications", notifications: "events", events: "done" }[s.phase];
    s.index = 0;
    await ctx.state.set(key, s);
  }
  let action = s.phase,
    records = [{ fields: { Name: "unused" } }],
    to = "",
    subject = "Meeting Summary",
    message = "",
    event = {
      summary: "unused",
      start: { dateTime: "2000-01-01T00:00:00Z" },
      end: { dateTime: "2000-01-01T01:00:00Z" },
    },
    pending = "";
  if (action !== "done") {
    pending = key + ":" + action + ":" + s.index;
    const x = s.plan[action][s.index];
    if (action === "tasks")
      records = [
        {
          fields: {
            Name: x.name,
            Description: x.description,
            "Due Date": x.due_date,
            Priority: x.priority,
            Project: [x.project_name],
          },
        },
      ];
    if (action === "notifications") {
      to = x.email;
      message = "Summary:\n" + s.summary + "\n\nAction Items:\n" + x.action_items;
    }
    if (action === "events")
      event = {
        summary: x.name,
        start: { dateTime: x.start },
        end: { dateTime: x.end },
        attendees: [{ email: x.attendee }],
        conferenceData: {
          createRequest: {
            requestId: meetingId + "-" + s.index,
            conferenceSolutionKey: { type: "hangoutsMeet" },
          },
        },
      };
    s.pending = pending;
    await ctx.state.set(key, s);
  }
  return { key, action, pending, records, to, subject, message, event, baseId, table, calendarId };
}

