async function confirm({ key, kind, records, messageId, eventId }, ctx) {
  const s = await ctx.state.get(key);
  if (!s?.pending || s.phase !== kind) throw Error("Missing pending operation");
  if (kind === "tasks" && (!Array.isArray(records) || !records[0]?.id))
    throw Error("Unknown Airtable result");
  if (kind === "notifications" && !messageId) throw Error("Unknown Gmail result");
  if (kind === "events" && !eventId) throw Error("Unknown Calendar result");
  s.pending = null;
  s.index++;
  await ctx.state.set(key, s);
  return { ok: true };
}

export default async function f(input, ctx) {
  return confirm({ ...input, kind: "tasks" }, ctx);
}

